import logging
from taf.analyzer.pcap.tshark_reader import TsharkReader
from taf.analyzer.pcap.pcap_packet import PcapPacket
from taf.analyzer.pcap.exceptions import TsharkCommandNotExisted


class PcapParser(object):

    def __init__(self):
        self._tshark_command = None

    def setup_tshark_command(self, command):
        """
        Setup tshark command for loading pcap packets.
        :param command: tshark command instance.
        :type command: TsharkCommand
        """
        self._tshark_command = command
        logging.info("tshark version info:\n{}".format(self._tshark_command.tshark_version))

    def config_filter(self, filter):
        """
        Configure packet filter condition when loading pcap packets.
        :param filter: Wireshark filter condition, e.g 'ngap.misc == 3'.
        :type filter: str
        """
        if self._tshark_command is None:
            raise TsharkCommandNotExisted("should call setup_tshark_command firstly")

        if filter is None:
            self._tshark_command.clear_filter()
        else:
            self._tshark_command.insert_filter(filter)

    def get_packets(self):
        """
        Get pcap packets.
        :return: pcap packets.
        :rtype: PcapPacket List
        """
        packets = [PcapPacket(pdml_packet) for pdml_packet in TsharkReader(self._tshark_command)]
        logging.info("have read {} packets".format(len(packets)))
        return packets

    def get_field_value_by_name(self, field_name, attribute="show"):
        """
        Get field values of packets by specified field name.
        :param field_name: field name.
        :type field_name: str
        :param attribute: field attribute name, e.g 'value', 'showname', 'show', default 'show'.
        :type attribute: str
        :return: field value list.
        :rtype: List
        """
        field_values = []
        for packet in self.get_packets():
            try:
                value = packet.get_field_value_by_name(field_name, attribute)
                field_values.append(value)
            except KeyError:
                continue

        return field_values

    def get_field_value_by_xpath(self, field_xpath, attribute="show"):
        """
        Get field values of packets by specified field xpath.
        :param field_xpath: field xpath.
        :type field_xpath: str
        :param attribute: field attribute name, e.g 'value', 'showname', 'show', default 'show'.
        :type attribute: str
        :return: field value list.
        :rtype: List
        """
        field_values = []
        for packet in self.get_packets():
            try:
                value = packet.get_field_value_by_xpath(field_xpath, attribute)
                field_values.append(value)
            except KeyError:
                continue

        return field_values

    def extend_one_element_list(self, field_values):
        ret_values = []
        for value in field_values:
            ret_values += value
        return ret_values
